(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');let W=0,H=0,dpr=1,last=0,worldTime=0,running=false,dead=false,won=false,spawnTimer=1.5,kills=0,souls=0,screenShake=0,toastTimer=0;
