const arena={bossSpawned:false};
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function lerp(a,b,t){return a+(b-a)*t}function dist(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}function rand(a,b){return a+Math.random()*(b-a)}function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
const cam={x:0,z:-5,yaw:0};
function project(x,y,z){let dx=x-cam.x,dz=z-cam.z,cs=Math.cos(cam.yaw),sn=Math.sin(cam.yaw),rx=dx*cs-dz*sn,rz=dx*sn+dz*cs;let focal=Math.min(W,H)*.83,depth=rz+10;if(depth<.1)depth=.1;return{x:W/2+rx*focal/depth,y:H*.47+(1.6-y)*focal/depth,s:focal/depth,depth}}
function makeWorld(){props.length=0;for(let i=0;i<38;i++){let side=i%2?1:-1,z=rand(-15,22),x=side*rand(8,19);props.push({type:Math.random()<.54?'tree':'rock',x,z,size:rand(.65,1.5),rot:rand(0,6.28),h:rand(2.4,5.2)})}for(let i=0;i<15;i++)props.push({type:'shrine',x:rand(-18,18),z:rand(-12,22),size:rand(.5,1.1),rot:0});for(let i=0;i<160;i++)petals.push({x:rand(-18,18),z:rand(-18,22),y:rand(.5,5),v:rand(.3,1),phase:rand(0,6.28),s:rand(1,3)})}makeWorld();
function drawGround(){let horizon=project(0,0,25).y;let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1c2824');sky.addColorStop(.52,'#465649');sky.addColorStop(.7,'#8e7754');sky.addColorStop(1,'#34392e');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.beginPath();ctx.moveTo(0,horizon);for(let x=0;x<=W;x+=35){let y=horizon+Math.sin(x*.007+worldTime*.03)*24+Math.sin(x*.021)*14;ctx.lineTo(x,y)}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fillStyle='#28342f';ctx.fill();let glow=ctx.createRadialGradient(W*.72,H*.24,4,W*.72,H*.24,Math.min(W,H)*.4);glow.addColorStop(0,'rgba(221,185,120,.18)');glow.addColorStop(1,'rgba(220,172,102,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);let g=ctx.createLinearGradient(0,H*.48,0,H);g.addColorStop(0,'#65583e');g.addColorStop(.25,'#4e4934');g.addColorStop(1,'#202821');ctx.fillStyle=g;ctx.fillRect(0,H*.48,W,H*.52);let pts=[project(-3.2,0,-12),project(3.2,0,-12),project(9,0,26),project(-9,0,26)];ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();let road=ctx.createLinearGradient(0,H*.45,0,H);road.addColorStop(0,'#5e5540');road.addColorStop(1,'#514638');ctx.fillStyle=road;ctx.fill();for(let i=0;i<100;i++){let x=rand(-8,8),z=rand(-12,24),p=project(x,0,z),s=clamp(p.s*.014,.5,5);ctx.fillStyle=Math.random()>.5?'#8a7957':'#333b2d';ctx.globalAlpha=.18+Math.random()*.2;ctx.fillRect(p.x,p.y,s*2,s*.6)}ctx.globalAlpha=1;for(let i=0;i<5;i++){let x=-13+i*6.2,z=13+Math.sin(i*12)*3,p=project(x,0,z);ctx.fillStyle='#30372e';ctx.beginPath();ctx.moveTo(p.x-70*p.s/65,p.y);ctx.lineTo(p.x,p.y-130*p.s/65);ctx.lineTo(p.x+90*p.s/65,p.y);ctx.fill()}}
function drawTree(o){let p=project(o.x,0,o.z),s=p.s*o.size;if(s<1)return;let ht=o.h*s*.43,w=s*.52;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(o.rot*.05);ctx.fillStyle='#302d22';ctx.fillRect(-w*.1,-ht*.45,w*.2,ht*.48);for(let i=0;i<4;i++){let yy=-ht*(.35+i*.2),ww=w*(1-i*.17);ctx.beginPath();ctx.moveTo(0,yy-ht*.35);ctx.lineTo(-ww,yy+ht*.23);ctx.lineTo(ww,yy+ht*.23);ctx.closePath();ctx.fillStyle=['#813d2f','#a54e36','#9c6438','#4d4730'][i];ctx.globalAlpha=.84;ctx.fill()}ctx.globalAlpha=1;ctx.restore()}
function drawProp(o){let p=project(o.x,0,o.z),s=p.s*o.size;if(p.depth<0||s<.7)return;if(o.type==='tree'){drawTree(o);return}if(o.type==='rock'){ctx.fillStyle='#46483b';ctx.beginPath();ctx.ellipse(p.x,p.y-s*.14,s*.6,s*.26,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#5e5c4a';ctx.beginPath();ctx.moveTo(p.x-s*.48,p.y-s*.12);ctx.lineTo(p.x-s*.3,p.y-s*.7);ctx.lineTo(p.x+s*.14,p.y-s*.82);ctx.lineTo(p.x+s*.55,p.y-s*.18);ctx.closePath();ctx.fill();return}ctx.fillStyle='#272720';ctx.fillRect(p.x-s*.22,p.y-s*.55,s*.44,s*.55);ctx.fillStyle='#6d5b3e';ctx.fillRect(p.x-s*.37,p.y-s*.72,s*.74,s*.13);ctx.fillStyle='#df9d4c';ctx.globalAlpha=.7+Math.sin(worldTime*3+o.x)*.18;ctx.shadowColor='#efa852';ctx.shadowBlur=s*1.6;ctx.fillRect(p.x-s*.08,p.y-s*.48,s*.16,s*.24);ctx.shadowBlur=0;ctx.globalAlpha=1}
function drawPetals(dt){ctx.save();ctx.fillStyle='#c7774b';for(let f of petals){f.x+=Math.sin(worldTime*.8+f.phase)*dt*.6;f.z-=dt*f.v*.35;if(f.z<-18)f.z=22;let p=project(f.x,f.y+Math.sin(worldTime+f.phase)*.2,f.z);if(p.depth>0){ctx.globalAlpha=clamp(1-p.depth/80,.08,.56);ctx.beginPath();ctx.ellipse(p.x,p.y,f.s*p.s/70,f.s*p.s/150,Math.sin(worldTime+f.phase),0,Math.PI*2);ctx.fill()}}ctx.restore()}
function drawHuman(x,z,yaw,scale,bodyColor,armorColor,bladeColor,phase=0,isPlayer=false,boss=false){let p=project(x,0,z);if(p.depth<.1)return;let s=p.s*scale,bob=isPlayer?Math.sin(player.anim*9)*s*.018:Math.sin(worldTime*5+phase)*s*.012,forward=yaw-cam.yaw;ctx.save();ctx.translate(p.x,p.y+bob);ctx.rotate(forward);let leg=s*.36,torso=s*.58,head=s*.18,armSwing=isPlayer&&player.attack>0?Math.sin(player.attack/.45*Math.PI)*s*.3:Math.sin(phase+worldTime*4)*s*.025;ctx.fillStyle='rgba(8,10,8,.45)';ctx.beginPath();ctx.ellipse(0,-2,s*.28,s*.09,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=bodyColor;ctx.beginPath();ctx.moveTo(-s*.2,-leg);ctx.lineTo(s*.19,-leg);ctx.lineTo(s*.28,-leg-torso*.62);ctx.lineTo(-s*.31,-leg-torso*.62);ctx.closePath();ctx.fill();ctx.fillStyle=armorColor;ctx.fillRect(-s*.14,-leg,s*.105,leg);ctx.fillRect(s*.04,-leg,s*.105,leg);ctx.fillStyle='#302d27';ctx.fillRect(-s*.18,-s*.06,s*.17,s*.07);ctx.fillRect(s*.01,-s*.06,s*.17,s*.07);ctx.fillStyle=bodyColor;ctx.beginPath();ctx.moveTo(-s*.26,-leg-torso*.6);ctx.lineTo(s*.25,-leg-torso*.6);ctx.lineTo(s*.34,-leg-torso*.04);ctx.lineTo(-s*.32,-leg-torso*.04);ctx.closePath();ctx.fill();ctx.fillStyle='#a78b59';ctx.fillRect(-s*.27,-leg-torso*.17,s*.55,s*.06);ctx.fillStyle=armorColor;ctx.beginPath();ctx.moveTo(-s*.22,-leg-torso*.55);ctx.lineTo(s*.19,-leg-torso*.55);ctx.lineTo(s*.25,-leg-torso*.18);ctx.lineTo(-s*.23,-leg-torso*.18);ctx.closePath();ctx.fill();ctx.strokeStyle='#c1a06a';ctx.lineWidth=Math.max(1,s*.025);ctx.beginPath();ctx.moveTo(-s*.19,-leg-torso*.5);ctx.lineTo(s*.17,-leg-torso*.23);ctx.stroke();ctx.strokeStyle=bodyColor;ctx.lineWidth=s*.13;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-s*.2,-leg-torso*.52);ctx.lineTo(-s*.35,-leg-torso*.18);ctx.lineTo(-s*.26,-leg-torso*.02);ctx.stroke();ctx.beginPath();ctx.moveTo(s*.19,-leg-torso*.52);ctx.lineTo(s*.34+armSwing,-leg-torso*.3);ctx.lineTo(s*.32+armSwing,-leg-torso*.08);ctx.stroke();ctx.fillStyle='#b88d68';ctx.beginPath();ctx.arc(0,-leg-torso*.68,head,0,Math.PI*2);ctx.fill();ctx.fillStyle=armorColor;ctx.beginPath();ctx.moveTo(-head*1.2,-leg-torso*.68);ctx.lineTo(0,-leg-torso*.68-head*.4);ctx.lineTo(head*1.2,-leg-torso*.68);ctx.lineTo(head*.85,-leg-torso*.77);ctx.lineTo(-head*.85,-leg-torso*.77);ctx.fill();if(boss){ctx.fillStyle='#c84c35';ctx.beginPath();ctx.moveTo(-head*.7,-leg-torso*.68);ctx.lineTo(-head*2.7,-leg-torso*.78);ctx.lineTo(-head*1.1,-leg-torso*.58);ctx.moveTo(head*.7,-leg-torso*.68);ctx.lineTo(head*2.7,-leg-torso*.78);ctx.lineTo(head*1.1,-leg-torso*.58);ctx.fill()}let sx=s*.47+armSwing*.5,sy=-leg-torso*.12;ctx.strokeStyle='#302923';ctx.lineWidth=s*.06;ctx.beginPath();ctx.moveTo(s*.28+armSwing,sy);ctx.lineTo(sx,sy);ctx.stroke();ctx.strokeStyle=bladeColor;ctx.lineWidth=Math.max(1,s*.045);ctx.beginPath();ctx.moveTo(sx,sy);let slash=isPlayer&&player.attack>0?Math.sin(player.attack/.45*Math.PI)*s*.26:0;ctx.lineTo(sx+s*.78,sy-s*.48-slash);ctx.stroke();ctx.strokeStyle='#dacda9';ctx.lineWidth=Math.max(.5,s*.018);ctx.beginPath();ctx.moveTo(sx+s*.07,sy-s*.04);ctx.lineTo(sx+s*.72,sy-s*.45-slash);ctx.stroke();if(isPlayer&&player.guard){ctx.strokeStyle='rgba(231,207,155,.45)';ctx.lineWidth=s*.05;ctx.beginPath();ctx.arc(0,-leg-torso*.3,s*.54,-1.1,.75);ctx.stroke()}if(!isPlayer){let e=enemies.find(q=>q.x===x&&q.z===z);if(e&&e.windup>.01){ctx.fillStyle=e.heavy?'#e79a56':'#e0c481';ctx.globalAlpha=.55+.4*Math.sin(worldTime*18);ctx.beginPath();ctx.arc(0,-leg-torso-head*2,s*.075,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}ctx.restore()}
function particle(x,z,color,count=9,power=2){for(let i=0;i<count;i++)particles.push({x,z,y:rand(.4,1.7),vx:rand(-power,power),vz:rand(-power,power),vy:rand(.5,3),life:rand(.2,.6),max:.6,color,size:rand(1,3)})}function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.z+=p.vz*dt;p.y+=p.vy*dt;p.vy-=5*dt;if(p.life<=0)particles.splice(i,1)}}function drawParticles(){for(let p of particles){let q=project(p.x,p.y,p.z);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(q.x,q.y,p.size*q.s/50,p.size*q.s/50)}ctx.globalAlpha=1}
function spawnEnemy(boss=false){let a=rand(0,Math.PI*2),r=rand(7,11),e={x:player.x+Math.cos(a)*r,z:player.z+Math.sin(a)*r,yaw:0,hp:boss?240:65,max:boss?240:65,st:0,windup:0,attackCD:rand(.5,2),hit:0,dead:0,boss,heavy:boss,phase:rand(0,6.28),speed:boss?1.18:rand(1.05,1.45)};e.yaw=Math.atan2(player.x-e.x,player.z-e.z);enemies.push(e);if(boss){arena.bossSpawned=true;document.getElementById('bossbar').style.display='block';document.getElementById('bossname').textContent='THE HOLLOW GENERAL';showToast('THE HOLLOW GENERAL HAS FOUND YOU')}else showToast('A WRAITH STIRS')}
function showToast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');toastTimer=2.2}function updateHud(){document.getElementById('hpBar').style.width=player.hp+'%';document.getElementById('hpText').textContent=Math.ceil(player.hp)+' / 100';document.getElementById('stBar').style.width=player.st+'%';document.getElementById('stText').textContent=Math.ceil(player.st)+' / 100';document.getElementById('souls').textContent=souls;document.getElementById('kills').textContent=kills;let boss=enemies.find(e=>e.boss);if(boss){document.getElementById('bossHp').style.width=(boss.hp/boss.max*100)+'%';document.getElementById('postureStat').style.display='block';document.getElementById('poBar').style.width=(boss.st)+'%';document.getElementById('poText').textContent=Math.floor(boss.st)+'%'}else document.getElementById('postureStat').style.display='none'}
function hitEnemy(e,dmg,posture=20){if(e.dead)return;e.hp-=dmg;e.st=clamp(e.st+posture,0,100);e.hit=.2;screenShake=Math.max(screenShake,.14);particle(e.x,e.z,e.boss?'#d77b52':'#bf7b58',11,2.4);if(e.st>=100){e.windup=0;e.attackCD=Math.max(e.attackCD,.8);e.st=0;e.hp-=15;showToast('POSTURE BROKEN')}if(e.hp<=0){e.dead=.7;e.windup=0;kills++;souls+=e.boss?150:20;showToast(e.boss?'THE GENERAL FALLS':'WRAITH VANQUISHED');if(e.boss){won=true;setTimeout(()=>endGame(true),1100)}else if(kills>=5&&!arena.bossSpawned){spawnTimer=0}}}
function playerAttack(heavy=false){if(!running||dead||won||player.cool>0||player.st<(heavy?34:15))return;player.attack=heavy?.64:.42;player.cool=heavy?.7:.37;player.st-=heavy?34:15;player.comboTime=.7;player.combo=(player.combo+1)%3;let range=heavy?2.45:1.9;for(const e of enemies){if(e.dead)continue;let dx=e.x-player.x,dz=e.z-player.z,d=Math.hypot(dx,dz),a=Math.atan2(dx,dz);if(d<range&&Math.abs(angleDiff(a,player.yaw))<(heavy?.95:.82)){hitEnemy(e,heavy?42:25,heavy?40:26);let push=heavy?.9:.55;e.x+=Math.sin(player.yaw)*push;e.z+=Math.cos(player.yaw)*push}}}
function dodge(){if(!running||dead||player.st<28||player.dodge>0)return;player.st-=28;player.dodge=.38;player.invuln=.45;let mx=(keys.d?1:0)-(keys.a?1:0),mz=(keys.s?1:0)-(keys.w?1:0);if(!mx&&!mz){mx=Math.sin(player.yaw);mz=Math.cos(player.yaw)}let l=Math.hypot(mx,mz)||1;player.x+=mx/l*1.4;player.z+=mz/l*1.4;player.yaw=Math.atan2(mx,mz);particle(player.x,player.z,'#c27a53',5,.7)}
function parry(){if(!running||dead)return;player.guard=true;let success=false;for(let e of enemies){if(e.dead||e.windup<=0||dist(e,player)>2.35)continue;let a=Math.atan2(player.x-e.x,player.z-e.z);if(Math.abs(angleDiff(a,e.yaw))<.8){e.windup=0;e.attackCD=.8;e.st=clamp(e.st+65,0,100);e.hit=.18;success=true;player.st=clamp(player.st+18,0,100);particle(e.x,e.z,'#e5d19b',16,3);screenShake=.22;showToast('PERFECT PARRY')}}if(!success)player.guard=true;setTimeout(()=>player.guard=false,250)}
function damagePlayer(dmg,e){if(player.invuln>0||dead)return;if(player.guard){let a=Math.atan2(e.x-player.x,e.z-player.z);if(Math.abs(angleDiff(a,player.yaw))<1.3){dmg*=.16;player.st=Math.max(0,player.st-11);particle(player.x,player.z,'#d7c593',4,1);if(dmg<3)return}}player.hp-=dmg;player.hitFlash=.22;player.invuln=.35;screenShake=.28;particle(player.x,player.z,'#aa463b',8,2);if(player.hp<=0){player.hp=0;dead=true;setTimeout(()=>endGame(false),650)}}
function updateEnemy(e,dt){if(e.dead){e.dead-=dt;return}if(e.hit>0)e.hit-=dt;e.attackCD-=dt;let dx=player.x-e.x,dz=player.z-e.z,d=Math.hypot(dx,dz),target=Math.atan2(dx,dz);e.yaw+=angleDiff(target,e.yaw)*Math.min(1,dt*5);if(e.windup>0){e.windup-=dt;if(e.windup<=0){let d2=dist(e,player),a=Math.atan2(player.x-e.x,player.z-e.z);if(d2<(e.boss?2.65:2.05)&&Math.abs(angleDiff(a,e.yaw))<1.08)damagePlayer(e.boss?25:14,e);else if(d2<3.1&&e.heavy)damagePlayer(18,e);e.attackCD=e.boss?1.25:1.6}return}if(d>(e.boss?2.1:1.5)){let speed=e.speed*(e.boss?1:.8);e.x+=Math.sin(e.yaw)*speed*dt;e.z+=Math.cos(e.yaw)*speed*dt}if(d<(e.boss?2.7:2.15)&&e.attackCD<=0)e.windup=e.boss?.72:.58}
function update(dt){worldTime+=dt;player.anim+=dt;player.cool=Math.max(0,player.cool-dt);player.attack=Math.max(0,player.attack-dt);player.invuln=Math.max(0,player.invuln-dt);player.dodge=Math.max(0,player.dodge-dt);player.hitFlash=Math.max(0,player.hitFlash-dt);player.st=clamp(player.st+(player.guard?2:23)*dt,0,100);if(player.comboTime>0)player.comboTime-=dt;else player.combo=0;let mx=(keys.d?1:0)-(keys.a?1:0),mz=(keys.s?1:0)-(keys.w?1:0),l=Math.hypot(mx,mz);if(l){mx/=l;mz/=l;let speed=keys.shift?6.2:4.2;if(player.dodge>0)speed=6;player.x=clamp(player.x+mx*speed*dt,-15,15);player.z=clamp(player.z+mz*speed*dt,-13,23);player.yaw=Math.atan2(mx,mz)}let follow=1-Math.exp(-dt*3.4);cam.x=lerp(cam.x,player.x,follow);cam.z=lerp(cam.z,player.z-5.3,follow);cam.yaw=lerp(cam.yaw,0,follow);if(kills>=5&&!arena.bossSpawned&&spawnTimer<=0)spawnEnemy(true);else if(enemies.length<3&&!arena.bossSpawned&&kills<5){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy(false);spawnTimer=rand(2.4,4)}}for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];updateEnemy(e,dt);if(e.dead<0)enemies.splice(i,1)}updateParticles(dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}screenShake=Math.max(0,screenShake-dt);updateHud()}
function render(dt){ctx.save();if(screenShake>0)ctx.translate(rand(-screenShake,screenShake)*14,rand(-screenShake,screenShake)*14);drawGround();let objects=props.concat(enemies.filter(e=>!e.dead).map(e=>({type:'enemy',z:e.z,x:e.x,e})),[{type:'player',z:player.z,x:player.x}]).sort((a,b)=>b.z-a.z);for(let o of objects){if(o.type==='enemy'){let e=o.e;drawHuman(e.x,e.z,e.yaw,e.boss?1.25:1,e.boss?'#4b3029':'#413b31',e.boss?'#5e5143':'#625c4b',e.boss?'#e0b972':'#c3d1c2',e.phase,false,e.boss);if(e.hit>0){let p=project(e.x,1.1,e.z);ctx.fillStyle=`rgba(255,230,190,${e.hit*2})`;ctx.beginPath();ctx.arc(p.x,p.y,14,0,Math.PI*2);ctx.fill()}}else if(o.type==='player'){drawHuman(player.x,player.z,player.yaw,1,'#4c3028','#77705d','#d5d9c8',0,true);if(player.hitFlash>0){ctx.fillStyle=`rgba(197,50,40,${player.hitFlash*.18})`;ctx.fillRect(0,0,W,H)}}else drawProp(o)}drawPetals(dt);drawParticles();ctx.restore()}
function frame(now){let dt=Math.min(.045,(now-last)/1000||.016);last=now;if(running&&!dead&&!won)update(dt);render(dt);requestAnimationFrame(frame)}requestAnimationFrame(frame);
function begin(){document.getElementById('title').classList.add('hidden');running=true;showToast('THE ROAD REMEMBERS');player.hp=100;player.st=100;player.x=0;player.z=0;spawnTimer=.5}
function endGame(victory){running=false;let el=document.getElementById('ending');document.getElementById('endTitle').innerHTML=victory?'THE LANTERN<br>ENDURES':'THE DARK<br>CLAIMS ALL';document.getElementById('endText').textContent=victory?'The Hollow General has fallen. The pass is quiet once more. Somewhere, a single lantern burns against the coming dark.':'Your light fades beneath the old road. The mountain keeps its secrets — for now.';el.classList.remove('hidden')}
function restart(){player.hp=100;player.st=100;player.x=0;player.z=0;player.yaw=0;enemies.length=0;particles.length=0;kills=0;souls=0;dead=false;won=false;arena.bossSpawned=false;spawnTimer=.5;document.getElementById('bossbar').style.display='none';document.getElementById('ending').classList.add('hidden');begin()}
document.getElementById('begin').onclick=begin;document.getElementById('again').onclick=restart;addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='j')playerAttack(false);if(k==='k')playerAttack(true);if(k==='l')parry();if(k===' ')dodge()});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});document.querySelectorAll('.mobile-controls button').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(k==='j')playerAttack(false);else if(k==='k')playerAttack(true);else if(k==='l')parry();else if(k===' ')dodge();else keys[k]=true});for(let ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{if(k!=='j'&&k!=='k'&&k!=='l'&&k!==' ')keys[k]=false})});})();

